package com._8x8.herd.device_logs.upload.storage.s3;

import com._8x8.herd.device_logs.contract.ObjectMetadataKeys;
import com._8x8.herd.device_logs.upload.storage.LogObject;
import com._8x8.herd.device_logs.upload.storage.LogStorage;
import com._8x8.herd.device_logs.upload.storage.LogStorageException;
import com._8x8.herd.device_logs.upload.storage.StoreResult;

import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

import software.amazon.awssdk.core.exception.SdkException;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.S3Exception;

/**
 * Writes each file with one PutObject: Content-Length set, so the SDK streams the body instead of buffering it, and
 * If-None-Match: *, so S3 refuses to overwrite an object that already has the key (ADR 0011).
 */
public class S3LogStorage implements LogStorage {

    // S3 takes only US-ASCII metadata and about 2 KB per object. The other four values are a few dozen characters, so
    // this leaves room for them.
    private static final Pattern METADATA_VALUE = Pattern.compile("[\\x20-\\x7E]{1,1024}");

    private final S3Client s3;
    private final String bucket;

    public S3LogStorage(S3Client s3, String bucket) {
        this.s3 = s3;
        this.bucket = bucket;
    }

    @Override
    public StoreResult store(LogObject object, InputStream body) {
        String key = object.key().format();
        try {
            s3.putObject(request -> request.bucket(bucket).key(key).contentLength(object.contentLength())
                    .ifNoneMatch("*").metadata(metadata(object)),
                    RequestBody.fromInputStream(body, object.contentLength()));
            return StoreResult.STORED;
        } catch (S3Exception e) {
            if (isCollision(e)) {
                return StoreResult.KEY_EXISTS;
            }
            throw new LogStorageException(key, e);
        } catch (SdkException e) {
            throw new LogStorageException(key, e);
        }
    }

    // 412 when the object exists. 409 when another write to the same key is still in progress, which is the same
    // collision a moment earlier.
    private static boolean isCollision(S3Exception e) {
        return e.statusCode() == 412 || e.awsErrorDetails() != null
                && "ConditionalRequestConflict".equals(e.awsErrorDetails().errorCode());
    }

    // A value S3 would refuse is left out, so a strange User-Agent can't fail the upload. The processor reads a missing
    // field as unknown.
    private static Map<String, String> metadata(LogObject object) {
        Map<String, String> metadata = new HashMap<>();
        putIfStorable(metadata, ObjectMetadataKeys.USER_AGENT, object.userAgent());
        putIfStorable(metadata, ObjectMetadataKeys.SOURCE_IP, Optional.of(object.sourceIp()));
        putIfStorable(metadata, ObjectMetadataKeys.CERT_SERIAL, Optional.of(object.certSerial()));
        metadata.put(ObjectMetadataKeys.MANUAL, Boolean.toString(object.manual()));
        putIfStorable(metadata, ObjectMetadataKeys.ORIGINAL_NAME, Optional.of(object.originalName()));
        return metadata;
    }

    private static void putIfStorable(Map<String, String> metadata, String name, Optional<String> value) {
        value.filter(present -> METADATA_VALUE.matcher(present).matches())
                .ifPresent(present -> metadata.put(name, present));
    }
}

